const markOrderCreated = `-- name: MarkOrderCreated :execrows
UPDATE procurement.buyer_quote_acceptances
SET order_provisioning_state = 'ORDER_CREATED', order_no = $1, payment_deadline = $2, updated_at = $3
WHERE id = $4 AND order_provisioning_state = 'CREATING_ORDER'
`

type MarkOrderCreatedParams struct {
	OrderNo         *string
	PaymentDeadline *time.Time
	Now             time.Time
	ID              uuid.UUID
}

// 建單 worker 專用（系統內部，免 buyer_id）：以 job 引數裡的接受單 id 定位，且買家關閉後接受單的 buyer_id 會被設為 NULL，帶 buyer_id 會讓已建好的單記不回來。
func (q *Queries) MarkOrderCreated(ctx context.Context, arg MarkOrderCreatedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markOrderCreated,
		arg.OrderNo,
		arg.PaymentDeadline,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markOrderFailed = `-- name: MarkOrderFailed :execrows
UPDATE procurement.buyer_quote_acceptances
SET state = 'ORDER_FAILED', order_provisioning_state = 'ORDER_FAILED', order_failure_reason = $1, updated_at = $2
WHERE id = $3 AND order_provisioning_state = 'CREATING_ORDER'
`

type MarkOrderFailedParams struct {
	Reason *string
	Now    time.Time
	ID     uuid.UUID
}

// 建單的 River job 重試用盡時呼叫（A9-D19 S6 修訂）：同時轉成 ORDER_FAILED 並解除 live 鎖。
func (q *Queries) MarkOrderFailed(ctx context.Context, arg MarkOrderFailedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markOrderFailed, arg.Reason, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
